INSERT INTO Drinker (name, address) VALUES ('Drinker1', 'Addr1');
INSERT INTO Drinker (name, address) VALUES ('Drinker2', 'Addr2');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Drinker1', 'Bar1', 1);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Drinker2', 'Bar1', 1);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Beer1', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Beer2', 5.00);
INSERT INTO Likes (drinker, beer) VALUES ('Drinker1', 'Beer1');
INSERT INTO Likes (drinker, beer) VALUES ('Drinker2', 'Beer1');
INSERT INTO Likes (drinker, beer) VALUES ('Drinker2', 'Beer2');

